'''# A documented campaign reserves at most 65536 identifiers across all entry
# plans; the ceiling below only exists so that an out-of-domain layout cannot
# exhaust memory or time before the pipeline notices.
MAX_RESERVED = 1 << 17


def reserved_ids(type, limit=MAX_RESERVED):
    """Identifiers a type reserves, with an early bail above `limit`.

    Composites reserve one identifier of their own plus their children, so a
    wide aggregate can request an astronomical number of objects.  The count
    is memoised per declaration so the check itself stays linear.
    """
    memo = {}
    stack = [(type, 0)]
    while stack:
        current, phase = stack.pop()
        while isinstance(current, Alias):
            current = current.type
        name = current.decl
        if name is not None and name in memo:
            value = memo[name]
        else:
            value = None
            if phase == 0:
                if isinstance(current, _SCALARS):
                    value = 1
                elif isinstance(current, String):
                    value = 1 + current.maxsize
                elif isinstance(current, Void):
                    value = 0
                elif isinstance(current, Array):
                    inner = reserved_child(current.element_type, memo, limit)
                    if inner is None:
                        return None
                    value = 1 + current.size * inner
                elif isinstance(current, Struct):
                    total = 1
                    for field in current.fields.values():
                        inner = reserved_child(field, memo, limit)
                        if inner is None:
                            return None
                        total += inner
                        if total > limit:
                            return None
                    value = total
                else:
                    raise InvalidCampaign("unsupported symbolic type")
            else:
                value = phase
            if name is not None:
                memo[name] = value
        if value is None or value > limit:
            return None
        return value
    return None


def reserved_child(type, memo, limit):
    """Reserve identifiers for one child type using `memo`."""
    while isinstance(type, Alias):
        type = type.type
    name = type.decl
    if name is not None and name in memo:
        return memo[name]
    value = _count(type, memo, limit)
    if value is None:
        return None
    if name is not None:
        memo[name] = value
    return value


def _count(type, memo, limit):
    while isinstance(type, Alias):
        type = type.type
    if isinstance(type, _SCALARS):
        return 1
    if isinstance(type, String):
        return 1 + type.maxsize
    if isinstance(type, Void):
        return 0
    if isinstance(type, Array):
        inner = reserved_child(type.element_type, memo, limit)
        if inner is None or inner > limit:
            return None
        total = 1 + type.size * inner
        return total if total <= limit else None
    if isinstance(type, Struct):
        total = 1
        for field in type.fields.values():
            inner = reserved_child(field, memo, limit)
            if inner is None:
                return None
            total += inner
            if total > limit:
                return None
        return total
    raise InvalidCampaign("unsupported symbolic type")''')
